    security: { title: 'Redis · Security', url: 'https://redis.io/docs/latest/operate/oss_and_stack/management/security/' },
    pipeline: { title: 'Redis · Pipelining', url: 'https://redis.io/docs/latest/develop/using-commands/pipelining/' },
    latency: { title: 'Redis · Diagnosing latency', url: 'https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/' },
